_MODEL_XIAO_ESP32S3 // Has PSRAM\n\n#include "camera_pins.h"\n\nconst char* ssid = "";\nconst char* password = "";\n\nvoid startCameraServer();\nvoid setupLedFlash(int pin);\nOV5640 ov5640 = OV5640();\n\nvoid setup() {\n  Serial.begin(115200);\n  while(!Serial);\n  Serial.setDebugOutput(true);\n  Serial.println();\n\n  camera_config_t config;\n  config.ledc_channel = LEDC_CHANNEL_0;\n  config.ledc_timer = LEDC_TIMER_0;\n  config.pin_d0 = Y2_GPIO_NUM;\n  config.pin_d1 = Y3_GPIO_NUM;\n  config.pin_d2 = Y4_GPIO_NUM;\n  config.pin_d3 = Y5_GPIO_NUM;\n  config.pin_d4 = Y6_GPIO_NUM;\n  config.pin_d5 = Y7_GPIO_NUM;\n  config.pin_d6 = Y8_GPIO_NUM;\n  config.pin_d7 = Y9_GPIO_NUM;\n  config.pin_xclk = XCLK_GPIO_NUM;\n  config.pin_pclk = PCLK_GPIO_NUM;\n  config.pin_vsync = VSYNC_GPIO_NUM;\n  config.pin_href = HREF_GPIO_NUM;\n  config.pin_sscb_sda = SIOD_GPIO_NUM;\n  config.pin_sscb_scl = SIOC_GPIO_NUM;\n  config.pin_pwdn = PWDN_GPIO_NUM;\n  config.pin_reset = RESET_GPIO_NUM;\n  config.xclk_freq_hz = 20000000;\n  config.frame_size = FRAMESIZE_UXGA;\n  config.pixel_format = PIXFORMAT_JPEG; // for streaming\n  //config.pixel_format = PIXFORMAT_RGB565; // for face detection/recognition\n  config.grab_mode = CAMERA_GRAB_WHEN_EMPTY;\n  config.fb_location = CAMERA_FB_IN_PSRAM;\n  config.jpeg_quality = 12;\n  config.fb_count = 1;\n\n  // if PSRAM IC present, init with UXGA resolution and higher JPEG quality\n  //                      for larger pre-allocated frame buffer.\n  if(config.pixel_format == PIXFORMAT_JPEG){\n    if(psramFound()){\n      config.jpeg_quality = 10;\n      config.fb_count = 2;\n      config.grab_mode = CAMERA_GRAB_LATEST;\n    } else {\n      // Limit the frame size when PSRAM is not available\n      config.frame_size = FRAMESIZE_SVGA;\n      config.fb_location = CAMERA_FB_IN_DRAM;\n    }\n  } else {\n    // Best option for face detection/recognition\n    config.frame_size = FRAMESIZE_240X240;\n#if CONFIG_IDF_TARGET_ESP32S3\n    config.fb_count = 2;\n#endif\n  }\n\n  // camera init\n  esp_err_t err = esp_camera_init(&config);\n  if (err != ESP_OK) {\n    Serial.printf("Camera init failed with error 0x%x", err);\n    return;\n  }\n\n  sensor_t * s = esp_camera_sensor_get();\n  // --- OV5640 Heat Optimization: lower IO drive (0x302C bit[7:6] 11->00) ---\n  if (s && s->id.PID == OV5640_PID) {\n    s->set_reg(s, 0x302C, 0xC0, 0x00);\n  }\n  ov5640.start(s);\n\n    if (ov5640.focusInit() == 0) {\n    Serial.println("OV5640_Focus_Init Successful!");\n  }\n\n  if (ov5640.autoFocusMode() == 0) {\n    Serial.println("OV5640_Auto_Focus Successful!");\n  }\n\n// Setup LED FLash if LED pin is defined in camera_pins.h\n#if defined(LED_GPIO_NUM)\n  setupLedFlash(LED_GPIO_NUM);\n#endif\n\n  WiFi.begin(ssid, password);\n  WiFi.setSleep(false);\n\n  while (WiFi.status() != WL_CONNECTED) {\n    delay(500);\n    Serial.print(".");\n  }\n  Serial.println("");\n  Serial.println("WiFi connected");\n\n  startCameraServer();\n\n  Serial.print("Camera Ready! Use \'http://");\n  Serial.print(WiFi.localIP());\n  Serial.println("\' to connect");\n}\n\nvoid loop() {\n  uint8_t rc = ov5640.getFWStatus();\n  Serial.printf("FW_STATUS = 0x%x\\n", rc);\n\n  if (rc == -1) {\n    Serial.println("Check your OV5640");\n  } else if (rc == FW_STATUS_S_FOCUSED) {\n    Serial.println("Focused!");\n  } else if (rc == FW_STATUS_S_FOCUSING) {\n    Serial.println("Focusing!");\n  }\n}\n\n'})}),"\n",(0,r.jsx)(n.h3,{id:"gr\xe1fico-de-resultados",children:"Gr\xe1fico de resultados"}),"\n",(0,r.jsx)(n.admonition,{type:"tip",children:(0,r.jsx)(n.p,{children:"A resolu\xe7\xe3o precisa ser superior a 1280*1024 para ver o efeito de foco; a tela ir\xe1 travar e voc\xea precisar\xe1 aguardar um pouco enquanto o foco \xe9 ajustado."})}),"\n",(0,r.jsx)("div",{style:{textAlign:"center"},children:(0,r.jsx)("img",{src:"https://files.seeedstudio.com/wiki/SeeedStudio-XIAO-ESP32S3/img/OV5640.gif",style:{width:700,height:"auto"}})}),"\n",(0,r.jsx)(n.h4,{id:"m\xe9todo-2",children:"M\xe9t